def rd(p): return open(p, encoding="utf-8").read()
if all(os.path.exists(p) and MARK in rd(p) for p in SPEC):
    print("  OK      already applied"); sys.exit(0)
bad=[]; texts={}
for p,(kind,v) in SPEC.items():
    if kind=="new":
        if os.path.exists(p) and MARK not in rd(p): bad.append(p+" exists"); 
        continue
    if not os.path.exists(p): bad.append(p+" missing"); continue
    t=rd(p)
    if MARK in t: bad.append(p+" already patched"); continue
    if kind=="full":
        import hashlib
        norm=t.rstrip(chr(10))+chr(10)
        if hashlib.sha256(norm.encode()).hexdigest()!=v[0]: bad.append(p+" differs from the S192 version it was made for")
        texts[p]=v[1]; continue
    pos=[]
    for i,(o,n) in enumerate(v):
        if t.count(o)!=1: bad.append("%s hunk %d found %d"%(p,i,t.count(o)))
        else: pos.append((t.index(o),o,n))
    pos.sort()
    for a,b in zip(pos,pos[1:]):
        if a[0]+len(a[1])>b[0]: bad.append(p+" overlapping hunks")
    for st,o,n in reversed(pos): t=t[:st]+n+t[st+len(o):]
    texts[p]=t
if bad: sys.exit("Anchor check failed, nothing written:\n  "+"\n  ".join(bad))
for p,(kind,v) in SPEC.items():
    t=v if kind=="new" else texts[p]
    os.makedirs(os.path.dirname(p) or ".",exist_ok=True)
    open(p,"w",encoding="utf-8").write(t); print("  PATCHED",p)
print("S193 applied. Next: git add -A && git commit -m \"S193: PIP power\" && git push")
